import org.eclipse.rdf4j.query.algebra.SingletonSet;
import org.eclipse.rdf4j.query.algebra.ValueConstant;
import org.eclipse.rdf4j.query.algebra.evaluation.QueryEvaluationStep;
import org.eclipse.rdf4j.query.algebra.evaluation.impl.QueryEvaluationContext;
import org.junit.jupiter.api.Test;

class NoFilterPlanningTest {
	@Test
	void emptyPlanningStillDelegatesAndToleratesLateCollectorCallbacks() {
		class CapturingRoot extends SingletonSet {
			QueryModelVisitor<?> visitor;

			@Override
			public <X extends Exception> void visit(QueryModelVisitor<X> v) throws X {
				visitor = v;
				super.visit(v);
			}

			@SuppressWarnings("unchecked")
			void report(QueryModelNode later) {
				later.visit((QueryModelVisitor<RuntimeException>) visitor);
			}
		}
		QueryEvaluationStep step = bindings -> QueryEvaluationStep.EMPTY_ITERATION;
		var root = new CapturingRoot();
		var vf = SimpleValueFactory.getInstance();
		var context = AdaptiveFilterEvaluationStep.planningContext(root,
				new QueryEvaluationContext.Minimal(null, vf, null));
		assertTrue(AdaptiveFilterEvaluationStep.isPlanningContext(context));
		assertFalse(AdaptiveFilterEvaluationStep.includesGraphRestrictionRegion(context));
		assertSame(step, AdaptiveFilterEvaluationStep.filter(context, step));
		// No filter in the indexed tree. A downstream extension may still hold the visitor.
		root.report(new Filter(new SingletonSet(), new ValueConstant(vf.createLiteral(true))));
		assertDoesNotThrow(() -> AdaptiveFilterEvaluationStep.recordPrepared(context, null, step));
		assertNull(AdaptiveFilterEvaluationStep.prepare(null, null, context, null, () -> {
			throw new AssertionError("unreachable");
		}));
		assertSame(step, AdaptiveFilterEvaluationStep.scope(step, context));
	}
}
